def transform(grid):
    h,w=len(grid),len(grid[0])
    g=[row[:] for row in grid]
    pts=[(r,c) for r in range(h) for c in range(w) if grid[r][c] not in (0,2)]
    rs=[r for r in range(h) for c in range(w) if grid[r][c]==2]
    cs=[c for r in range(h) for c in range(w) if grid[r][c]==2]
    r0,r1=min(rs),max(rs); c0,c1=min(cs),max(cs)
    for r,c in pts:
        if r0<=r<=r1:
            for j in list(range(0,c0))+list(range(c1+1,w)):
                if g[r][j]==0:g[r][j]=2
        if r<r0:
            for i in range(r0):
                if g[i][c]==0:g[i][c]=2
        if r>r1:
            for i in range(r1+1,h):
                if g[i][c]==0:g[i][c]=2
    return g
